import 'package:flutter/material.dart'; import '../main.dart'; import '../models/produto.dart';
class EstoquePage extends StatefulWidget { const EstoquePage({super.key}); @override State<EstoquePage> createState() => _EstoquePageState(); }
class _EstoquePageState extends State<EstoquePage> { late Future<List<Produto>> _produtos; @override void initState() { super.initState(); _carregar(); } void _carregar() => _produtos = produtoProvider.listar(); Future<void> _recarregar() async { setState(_carregar); await _produtos; }
  Future<void> _alterar(Produto produto, int quantidade) async { if (quantidade < 0) return; await produtoProvider.atualizarQuantidade(produto, quantidade); await _recarregar(); }
  Future<void> _excluir(Produto produto) async { final confirmou = await showDialog<bool>(context: context, builder: (context) => AlertDialog(title: const Text('Excluir produto?'), content: Text('Remover ${produto.nome} do estoque?'), actions: [TextButton(onPressed: () => Navigator.pop(context, false), child: const Text('CANCELAR')), FilledButton(onPressed: () => Navigator.pop(context, true), child: const Text('EXCLUIR'))])); if (confirmou == true) { await produtoProvider.excluir(produto); await _recarregar(); } }
  @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('ESTOQUE')), body: FutureBuilder<List<Produto>>(future: _produtos, builder: (context, snapshot) { if (snapshot.connectionState != ConnectionState.done) return const Center(child: CircularProgressIndicator()); final produtos = snapshot.data ?? []; if (produtos.isEmpty) return const Center(child: Text('Nenhum produto cadastrado.')); return RefreshIndicator(onRefresh: _recarregar, child: ListView.separated(padding: const EdgeInsets.all(16), itemCount: produtos.length, separatorBuilder: (_, __) => const Divider(), itemBuilder: (_, i) { final p = produtos[i]; final baixo = p.quantidade <= 3; return Card(child: Padding(padding: const EdgeInsets.all(16), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text(p.nome, style: Theme.of(context).textTheme.titleLarge), Text(p.categoria), const SizedBox(height: 8), Text('R\$ ${p.preco.toStringAsFixed(2).replaceAll('.', ',')}', style: Theme.of(context).textTheme.titleMedium), if (baixo) const Padding(padding: EdgeInsets.only(top: 8), child: Chip(label: Text('ESTOQUE BAIXO'), avatar: Icon(Icons.warning_amber_rounded))), const SizedBox(height: 8), Row(children: [IconButton(onPressed: p.quantidade == 0 ? null : () => _alterar(p, p.quantidade - 1), icon: const Icon(Icons.remove_circle_outline)), Expanded(child: Text('Quantidade: ${p.quantidade}', textAlign: TextAlign.center)), IconButton(onPressed: () => _alterar(p, p.quantidade + 1), icon: const Icon(Icons.add_circle_outline)), IconButton(tooltip: 'Excluir', onPressed: () => _excluir(p), icon: const Icon(Icons.delete_outline, color: Colors.red))])]))); }); })); }
}
